@r1 w.request.request act=change mood=do words="the boat just behind the bench"
@r1.t w.request.target request=$r1 family=drawn mode=existing determiner=definite fill=description sort=boat description="the boat"
@r1.c1 w.request.constraint request=$r1 on=place attribute=drawn.relation value=behind operator=relation phase=result
@r1.c2 w.request.constraint request=$r1 on=place attribute=drawn.anchor value="the bench" operator=relation phase=selector
@r2 w.request.request act=change mood=do words="the bench just behind the tree"
@r2.t w.request.target request=$r2 family=drawn mode=existing determiner=definite fill=description sort=bench description="the bench"
@r2.c1 w.request.constraint request=$r2 on=place attribute=drawn.relation value=behind operator=relation phase=result
@r2.c2 w.request.constraint request=$r2 on=place attribute=drawn.anchor value="the tree" operator=relation phase=selector
@f4 w.request.filler text="the scene needs"

@f1 w.request.filler text="part of the scene"
@r1 w.request.request act=change mood=do words="how about the sun cut off by the top edge" predicate=how
@r1.t w.request.target request=$r1 family=drawn mode=existing determiner=definite fill=description sort=sun description="the sun"
@r1.c2 w.request.constraint request=$r1 on=attribute attribute=drawn.edge value=top words="cut off by the top edge" operator=eq phase=result
@r2 w.request.request act=change mood=do words="the cloud half behind the sun"
@r2.t w.request.target request=$r2 family=drawn mode=existing determiner=definite fill=description sort=cloud description="the cloud"
@r2.c1 w.request.constraint request=$r2 on=place attribute=drawn.behind value="the sun" operator=relation phase=selector
@f3 w.request.filler text="and that's this part of the scene"
@r2.c2 w.request.constraint request=$r2 on=attribute attribute=drawn.cover value=half words="half behind the sun" operator=eq phase=result

@f1 w.request.filler text="picture should look"
@r1 w.request.request act=change mood=do words="start with the sun half cut off by the top edge" predicate=start
@r1.t w.request.target request=$r1 family=drawn mode=existing determiner=definite fill=description sort=sun description="the sun"
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=drawn.edge value=top words="the top edge" operator=eq phase=result
@r1.c2 w.request.constraint request=$r1 on=attribute attribute=drawn.cover value=half words="half cut off by the top edge" operator=eq phase=result
@r2 w.request.request act=change mood=do words="then the cloud half hidden behind the sun" predicate=then
@r2.t w.request.target request=$r2 family=drawn mode=existing determiner=definite fill=description sort=cloud description="the cloud"
@r2.c1 w.request.constraint request=$r2 on=place attribute=drawn.behind value="the sun" operator=relation phase=selector
@f3 w.request.filler text="that's how the picture should look"
@r2.c2 w.request.constraint request=$r2 on=attribute attribute=drawn.cover value=half words="half hidden behind the sun" operator=eq phase=result
